-- 赛题锚定：高职「软件技术」专业群 · 核心岗位「Python 开发工程师」
SET NAMES utf8mb4;

INSERT INTO interview_job_tech_stack (job_position, tech_stack, status, remark, created_at, updated_at)
SELECT * FROM (
  SELECT 'Python 开发' AS job_position,
         'Python3, 面向对象, 标准库, FastAPI/Flask, SQL, MySQL, Redis, 爬虫基础, Git, Linux, 单元测试, 接口开发' AS tech_stack,
         1 AS status,
         '软件技术专业群核心就业岗位' AS remark,
         NOW() AS created_at,
         NOW() AS updated_at
) AS t
WHERE NOT EXISTS (
  SELECT 1 FROM interview_job_tech_stack j WHERE j.job_position = t.job_position
);

INSERT INTO knowledge_base (
  job_position, question_type, question, excellent_answer, difficulty, keywords,
  question_intent, answer_points, score_standard, suitable_level, remark, status, in_chroma, created_at, updated_at
)
SELECT * FROM (
  SELECT 'Python 开发' AS job_position, '技术面' AS question_type, '解释 Python 中列表、元组、集合、字典的区别与典型使用场景。' AS question, '列表可变有序可重复；元组不可变；集合无序去重；字典键值映射。列表适合动态序列，元组适合只读记录，集合适合去重求交并，字典适合检索映射。' AS excellent_answer, 2 AS difficulty, '列表,元组,集合,字典' AS keywords, '考察基础数据结构' AS question_intent, '可变性/有序性/去重/映射四维对比+场景' AS answer_points, '概念正确60；能举业务场景80；能提复杂度90' AS score_standard, '初级' AS suitable_level, '依据：《Python 程序设计基础（高职）》第3章' AS remark, 1 AS status, 0 AS in_chroma, NOW() AS created_at, NOW() AS updated_at
  UNION ALL SELECT 'Python 开发','技术面','什么是可变对象与不可变对象？对函数传参有什么影响？','不可变如 int/str/tuple，可变如 list/dict/set。传参传的是对象引用；对可变对象原地修改会影响调用方，对不可变对象“修改”通常产生新对象。',3,'可变对象,不可变,传参','考察对象模型','可变性定义；引用传递；副作用示例','说清引用与副作用80+','中级','依据：《Python 程序设计基础（高职）》第4章',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','深拷贝与浅拷贝的区别是什么？如何实现？','浅拷贝复制容器本身但共享嵌套对象；深拷贝递归复制。可用 copy.copy / copy.deepcopy，或切片/工厂方法视场景使用。',3,'深拷贝,浅拷贝,copy','考察拷贝语义','浅/深定义；陷阱；API','能指出嵌套可变陷阱85','中级','依据：《Python 核心编程实践》§2.4',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','解释 *args 与 **kwargs 的作用，并举一个封装日志函数的例子。','*args 收集位置参数为元组，**kwargs 收集关键字参数为字典，用于可变参数与包装器。日志函数可统一接收任意字段写入。',2,'args,kwargs,可变参数','考察函数基础','语法；解包；封装示例','能手写简单示例80','初级','依据：《Python 程序设计基础（高职）》第5章',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','装饰器是什么？请说明带参数装饰器的实现思路。','装饰器是高阶函数，用于在不修改原函数的情况下增强功能。带参装饰器通常三层嵌套：外层收装饰器参数，中层收函数，内层执行增强逻辑。',4,'装饰器,高阶函数','考察语法进阶','闭包；三层结构；functools.wraps','能画调用链90','高级','依据：1+X《Python 程序开发》中级技能点-函数高级',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','生成器与普通函数返回列表有何不同？yield 的作用？','生成器惰性产出，节省内存；yield 暂停并返回当前值，下次从断点继续。适合大数据流式处理。',3,'生成器,yield,惰性','考察迭代协议','惰性；状态保存；场景','结合内存对比85','中级','依据：《Python 核心编程实践》§5.2',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','列表推导式与生成器表达式有什么区别？','列表推导立即生成完整列表；生成器表达式返回迭代器按需计算。数据量大时优先生成器表达式。',2,'列表推导,生成器表达式','考察惯用写法','求值时机；内存；可读性','说清取舍75','初级','依据：《Python 程序设计基础（高职）》第6章',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','解释 GIL 是什么，它对多线程 CPU 密集任务有何影响？','GIL 保证同一进程同一时刻只有一个线程执行 Python 字节码。CPU 密集多线程难提速，可改用多进程或原生扩展；I/O 密集仍可受益。',4,'GIL,多线程,多进程','考察并发模型','GIL含义；适用场景；替代方案','能区分CPU/IO场景90','高级','依据：Python 官方文档 Concurrency FAQ（教学引用）',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','多线程、多进程、异步（asyncio）分别适合什么场景？','多线程适合 I/O；多进程适合 CPU；asyncio 适合高并发 I/O 且可用协程库。需结合任务类型与库生态选择。',4,'线程,进程,asyncio','考察并发选型','三类模型；优缺点；选型原则','有清晰决策树85','高级','依据：1+X《Python 程序开发》高级-并发编程',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','如何理解上下文管理器？with 语句解决了什么问题？','上下文管理器通过 __enter__/__exit__ 管理资源获取与释放，with 确保异常时也能清理，避免资源泄漏。',3,'with,上下文管理器','考察资源管理','协议方法；异常安全；自定义','能写简易示例85','中级','依据：《Python 核心编程实践》§6.1',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','Python 中异常处理的最佳实践有哪些？','捕获具体异常；不要裸 except；使用 finally/上下文释放资源；记录日志；必要时封装业务异常。',2,'异常,try,except','考察工程习惯','具体捕获；日志；资源释放','列举≥3点70','初级','依据：《软件技术专业实训指导书》异常处理规范',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','什么是虚拟环境？为什么项目要使用 venv/conda？','虚拟环境隔离依赖版本，避免全局污染与冲突，便于复现部署。venv 轻量，conda 兼顾二进制依赖。',2,'venv,依赖隔离','考察工程环境','隔离原因；导出 requirements；复现','提到 requirements.txt80','初级','依据：高职《Python Web 应用开发》环境搭建章节',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','解释模块、包、__init__.py 的作用。','模块是 .py 文件；包是含 __init__.py 的目录（命名空间）。用于组织代码与控制导出。',2,'模块,包,init','考察工程结构','定义；导入路径；相对导入注意点','结构清晰70','初级','依据：《Python 程序设计基础（高职）》第8章',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','面向对象三大特性在 Python 中如何体现？给出简单示例思路。','封装用类与访问约定；继承用子类扩展；多态用统一接口不同实现。可用动物叫声或支付策略举例。',2,'封装,继承,多态','考察OOP','三特性定义+示例','示例贴业务80','初级','依据：《面向对象程序设计（Python）》第2章',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','@staticmethod 与 @classmethod 的区别？','staticmethod 无绑定 cls/self，像普通函数放在类命名空间；classmethod 接收 cls，常用于工厂方法。',3,'staticmethod,classmethod','考察类机制','参数差异；使用场景','能举工厂方法例85','中级','依据：《面向对象程序设计（Python）》第4章',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','如何设计一个可扩展的策略模式支付模块（Python）？','定义支付接口/抽象基类，不同渠道实现同一 pay 方法，上下文持有策略并调用，新增渠道无需改核心流程。',4,'设计模式,策略模式','考察设计能力','接口；开闭原则；示例结构','体现开闭原则90','高级','依据：软件技术专业《软件设计基础》设计模式实训',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','解释 REST 接口的基本约束，设计一个用户查询 API。','资源导向、HTTP 动词语义、无状态。例：GET /api/users/{id} 返回用户 JSON，错误用合适状态码。',3,'REST,HTTP,API','考察接口设计','资源；动词；状态码；示例','能写路径与状态码80','中级','依据：1+X《Web 应用软件开发》接口规范',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','Flask 与 FastAPI 的主要差异是什么？你会如何选型？','Flask 轻量灵活；FastAPI 原生异步、类型注解与自动文档。高并发 API/需要文档生成优先 FastAPI，简单后台可用 Flask。',3,'Flask,FastAPI','考察Web框架','差异点；选型；生态','结合项目约束说明85','中级','依据：高职《Python Web 应用开发》框架比较',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','如何用 FastAPI 做请求参数校验？','依赖 Pydantic 模型，用类型注解与 Field 约束，框架自动校验并返回 422。可自定义校验器。',3,'FastAPI,Pydantic,校验','考察工程实践','模型；Field；错误响应','提到422与文档生成85','中级','依据：FastAPI 官方 Tutorial-Body（教学引用）',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','接口鉴权常见方案有哪些？JWT 的基本流程？','Session、API Key、OAuth2、JWT。JWT：登录签发 token，客户端携带，服务端验签解析声明，注意过期与密钥管理。',3,'JWT,鉴权','考察安全基础','方案对比；JWT三段；风险','提到过期与泄露风险85','中级','依据：《Web 安全基础（高职）》第5章',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','SQL 注入是什么？在 Python 中如何防护？','拼接不可信输入导致语句被篡改。应使用参数化查询/ORM，拒绝字符串拼接 SQL，并最小权限。',2,'SQL注入,安全','考察安全意识','原理；参数化；ORM','必须提到参数化查询才能及格','初级','依据：《Web 安全基础（高职）》第3章；OWASP Top10（教学引用）',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','解释事务的 ACID，并说明什么时候需要事务。','原子性、一致性、隔离性、持久性。转账、库存扣减等多步写操作需事务保证要么全成要么全败。',3,'事务,ACID','考察数据库基础','ACID释义；业务场景；回滚','场景贴切80','中级','依据：《数据库原理与应用（高职）》第7章',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','如何优化一条慢 SQL？说出你的排查步骤。','先 explain 看执行计划；检查索引与条件；避免选*；控制回表；必要时改写或加覆盖索引；结合慢日志。',4,'慢SQL,索引,explain','考察数据库调优','explain；索引；改写','有完整排查链90','高级','依据：《MySQL 数据库应用》性能优化实训指导',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','Redis 常见数据结构有哪些？缓存穿透/击穿/雪崩如何理解？','String/Hash/List/Set/ZSet 等。穿透：查不存在；击穿：热点过期；雪崩：大量同时过期。可用布隆、互斥重建、随机TTL等。',4,'Redis,缓存','考察缓存','结构；三类问题；对策','三类问题都说清85','高级','依据：《NoSQL 数据库技术》Redis 章节',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','爬虫中 robots 协议与合规要注意什么？','遵守 robots.txt 与网站条款，控制频率，不抓隐私与未授权数据，用于教学需脱敏与来源说明。',2,'爬虫,robots,合规','考察职业规范','协议；限速；隐私','强调合规一票否决','初级','依据：软件技术专业《网络爬虫技术》合规专章',1,0,NOW(),NOW()
