  UNION ALL SELECT 'Python 开发','技术面','如何做 Python 单元测试？pytest 的基本用法？','编写测试函数/类，用 assert 断言，pytest 发现并执行。可用 fixture 管理前置，mock 隔离外部依赖。',3,'pytest,单元测试','考察质量保障','用例结构；fixture；mock','能描述最小用例80','中级','依据：1+X《Python 程序开发》测试技能点',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','Git 的分支开发流程你怎么做？如何避免覆盖他人代码？','功能分支开发，PR/MR 评审后合并主干；先 pull/rebase 再 push；冲突本地解决；禁止强推共享分支。',2,'Git,分支,协作','考察协作规范','分支；评审；冲突处理','提到禁止强推75','初级','依据：《软件工程与项目管理》版本管理实训',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','Linux 上如何查看端口占用、进程与日志？','ss/netstat/lsof 看端口；ps/top 看进程；journalctl 或业务日志文件排查。部署时配合 systemd。',2,'Linux,运维基础','考察部署基础','端口；进程；日志命令','能报出常用命令70','初级','依据：《Linux 操作系统应用》服务管理章节',1,0,NOW(),NOW()
