  UNION ALL SELECT 'Python 开发','技术面','什么是类型注解？它能带来什么好处？','为变量/函数标注类型，提升可读性，配合 mypy/IDE 做静态检查，降低接口错误。',2,'类型注解,mypy','考察代码质量','语法；工具；收益','提到静态检查80','初级','依据：PEP 484（教学引用）；高职进阶课程讲义',1,0,NOW(),NOW()
  UNION ALL SELECT 'Python 开发','技术面','如何处理文件上传与大小限制？','校验后缀与 MIME，限制大小，重命名存储，病毒扫描（如有），路径防穿越，权限最小化。',3,'文件上传,安全','考察安全实践','校验；限制；存储安全','防路径穿越必须提到','中级','依据：《Web 安全基础（高职）》文件上传专节',1,0,NOW(),NOW()
